import os, re

# Load all grids from session
def load():
    d = os.environ['RLM_SESSION_DIR']
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end() :].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(c.isdigit() for c in r) for r in rows):
            G[k] = [[int(c) for c in r] for r in rows]
    return G

G = load()
print("All keys:", sorted(G.keys()))

for k in G:
    print(f"\n=== {k} ({G[k][0].__len__()}-{len(G[k][0])}) ===")
    for row in G[k]:
        print(' '.join(f'{x:2d}' for x in row))

